__defs["agent-edit-review"] = function (module, exports, require) {
/*
 * Pure helpers for reviewing an OpenCode agent's file edits.
 *
 * The plugin snapshots the notes the agent may edit, lets the agent work, then
 * compares the after-state with the snapshot. The chat panel reverts those
 * changes immediately and only writes back the files the learner approves.
 * Keeping the comparison here makes the safety rule testable without Obsidian.
 */
const { pathInside } = require("./ai-write-guard");
const { str } = require("./util");

function normalizeText(value) {
  if (value === null || value === undefined) return null;
  return String(value).replace(/\r\n?/g, "\n");
}

function isMarkdownPath(path) {
  return /\.md$/i.test(str(path));
}

/** Files the agent may touch: configured write folders, plus explicitly reviewed open notes. */
function isReviewablePath(path, roots) {
  if (!isMarkdownPath(path)) return false;
  return (Array.isArray(roots) ? roots : []).some((root) => pathInside(path, root));
}

function statusFor(before, after) {
  if (before === null && after === null) return "unchanged";
  if (before === null) return "added";
  if (after === null) return "deleted";
  return "modified";
}

function splitLines(value) {
  return value === null ? [] : String(value).split("\n");
}

/**
 * A compact, readable diff. It trims the unchanged prefix and suffix, then
 * lists the changed block. Very large edits are shortened in the middle so a
 * modal cannot freeze on a whole-file rewrite.
 */
function diffPreview(before, after, maxLines) {
  const oldText = normalizeText(before);
  const newText = normalizeText(after);
  if (oldText === newText) return { lines: [], added: 0, removed: 0, truncated: false };
  const a = splitLines(oldText);
  const b = splitLines(newText);
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) start++;
  let endA = a.length;
  let endB = b.length;
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) {
    endA--;
    endB--;
  }
  const removed = a.slice(start, endA);
  const added = b.slice(start, endB);
  const raw = [];
  if (start > 0) raw.push({ kind: "context", text: a[start - 1], oldNo: start, newNo: start });
  for (let i = 0; i < removed.length; i++) raw.push({ kind: "del", text: removed[i], oldNo: start + i + 1, newNo: null });
  for (let i = 0; i < added.length; i++) raw.push({ kind: "add", text: added[i], oldNo: null, newNo: start + i + 1 });
  if (endA < a.length) raw.push({ kind: "context", text: a[endA], oldNo: endA + 1, newNo: endB + 1 });
  const limit = Math.max(4, Math.round(Number(maxLines) || 80));
  const truncated = raw.length > limit;
  let lines = raw;
  if (truncated) {
    const half = Math.floor(limit / 2);
    lines = raw.slice(0, half).concat([{ kind: "meta", text: `... ${raw.length - limit} more changed lines ...`, oldNo: null, newNo: null }], raw.slice(-half));
  }
  return { lines, added: added.length, removed: removed.length, truncated };
}

function changeFor(path, before, after) {
  const oldText = normalizeText(before);
  const newText = normalizeText(after);
  return {
    path: str(path),
    status: oldText === newText ? "unchanged" : statusFor(oldText, newText),
    before: oldText,
    after: newText,
    diff: diffPreview(oldText, newText),
  };
}

/** Compare two path -> text maps. A missing key means the file did not exist. */
function compareSnapshots(beforeMap, afterMap) {
  const before = beforeMap instanceof Map ? beforeMap : new Map(Object.entries(beforeMap || {}));
  const after = afterMap instanceof Map ? afterMap : new Map(Object.entries(afterMap || {}));
  const paths = [...new Set([...before.keys(), ...after.keys()])].sort();
  const changes = [];
  for (const path of paths) {
    const oldText = before.has(path) ? normalizeText(before.get(path)) : null;
    const newText = after.has(path) ? normalizeText(after.get(path)) : null;
    if (oldText === newText) continue;
    changes.push(changeFor(path, oldText, newText));
  }
  return changes;
}

function summarize(changes) {
  const list = Array.isArray(changes) ? changes : [];
  const counts = { added: 0, modified: 0, deleted: 0 };
  for (const change of list) if (counts[change.status] !== undefined) counts[change.status]++;
  return { ...counts, total: list.length };
}

function selectedChanges(changes, selectedPaths) {
  const wanted = selectedPaths instanceof Set ? selectedPaths : new Set(Array.isArray(selectedPaths) ? selectedPaths : []);
  return (Array.isArray(changes) ? changes : []).filter((change) => wanted.has(change.path));
}

module.exports = {
  changeFor,
  compareSnapshots,
  diffPreview,
  isMarkdownPath,
  isReviewablePath,
  normalizeText,
  selectedChanges,
  statusFor,
  summarize,
};
};

/* ---- src/agent-edit-review-modal.js ---- */
__defs["agent-edit-review-modal"] = function (module, exports, require) {
const { Modal, Notice } = require("obsidian");
const { summarize } = require("./agent-edit-review");

const STATUS_LABELS = {
  added: "New note",
  modified: "Changed",
  deleted: "Deleted",
};

class AgentEditReviewModal extends Modal {
  constructor(app, plugin, changes, onDone) {
    super(app);
    this.plugin = plugin;
    this.changes = Array.isArray(changes) ? changes : [];
    this.onDone = onDone;
    this.applying = false;
  }

  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.addClass("qt-agent-review");
    contentEl.createEl("h3", { text: "Review agent edits" });
    contentEl.createEl("p", {
      cls: "setting-item-description",
      text:
        "OpenCode's edits are paused and have been removed from your notes. Nothing is saved until you press Apply selected. " +
        "Close this window or choose Discard to keep the notes unchanged.",
    });
    const summary = summarize(this.changes);
    contentEl.createEl("p", {
      cls: "qt-hint",
      text: `${summary.total} note${summary.total === 1 ? "" : "s"} changed: ${summary.added} added, ${summary.modified} modified, ${summary.deleted} deleted.`,
    });

    this.boxes = new Map();
    for (const change of this.changes) {
      const wrap = contentEl.createDiv({ cls: "qt-agent-file" });
      const head = wrap.createDiv({ cls: "qt-agent-file-head" });
      const check = head.createEl("input", { type: "checkbox", attr: { "aria-label": `Apply ${change.path}` } });
      check.checked = true;
      this.boxes.set(change.path, check);
      const label = head.createSpan({ cls: "qt-agent-file-name", text: change.path });
      label.title = change.path;
      head.createSpan({ cls: `qt-agent-status is-${change.status}`, text: STATUS_LABELS[change.status] || change.status });
      const counts = change.diff.added || change.diff.removed ? ` +${change.diff.added} -${change.diff.removed}` : "";
      if (counts) head.createSpan({ cls: "qt-agent-count", text: counts.trim() });

      const details = wrap.createEl("details", { cls: "qt-agent-details" });
      details.createEl("summary", { text: change.diff.lines.length ? "Show diff" : "No text changes" });
      if (change.diff.lines.length) {
        const pre = details.createEl("pre", { cls: "qt-agent-diff" });
        for (const line of change.diff.lines) {
          const row = pre.createDiv({ cls: `qt-diff-${line.kind}` });
          const marker = line.kind === "add" ? "+" : line.kind === "del" ? "-" : " ";
          row.setText(`${marker}${line.text === "" ? " " : line.text}`);
        }
      }
    }

    const row = contentEl.createDiv({ cls: "qt-row" });
    const discard = row.createEl("button", { text: "Discard all", cls: "qt-grow" });
    discard.addEventListener("click", () => this.close());
    const apply = row.createEl("button", { text: "Apply selected", cls: "mod-cta qt-grow" });
    apply.addEventListener("click", () => this.apply());
    this.applyButton = apply;
  }

  selectedPaths() {
    const out = [];
    for (const [path, box] of this.boxes || []) if (box && box.checked) out.push(path);
    return out;
  }

  async apply() {
    if (this.applying || !this.plugin || typeof this.plugin.applyAgentEdits !== "function") return;
    const paths = this.selectedPaths();
    if (!paths.length) {
      this.close();
      return;
    }
    this.applying = true;
    if (this.applyButton) {
      this.applyButton.disabled = true;
      this.applyButton.setText("Applying...");
    }
    try {
      const result = await this.plugin.applyAgentEdits(this.changes, paths);
      const applied = (result && result.applied) || [];
      const conflicts = (result && result.conflicts) || [];
      if (applied.length) {
        new Notice(
          `Applied agent edits to ${applied.length} note${applied.length === 1 ? "" : "s"}. Use "AI: undo the last agent edits" to reverse them.`,
          8000
        );
      }
      if (conflicts.length) {
        new Notice(
          `Skipped ${conflicts.length} note${conflicts.length === 1 ? "" : "s"} because they changed after the agent finished. Apply them again if you still want them.`,
          10000
        );
      }
      if (this.onDone) this.onDone(result);
      this.close();
    } catch (e) {
      if (this.applyButton) {
        this.applyButton.disabled = false;
        this.applyButton.setText("Apply selected");
      }
      new Notice(`Could not apply the agent edits: ${e && e.message ? e.message : e}`, 10000);
    } finally {
      this.applying = false;
    }
  }

  onClose() {
    this.contentEl.empty();
  }
}

module.exports = {
  AgentEditReviewModal,
};
};

/* ---- src/agent-write-guard.js ---- */
__defs["agent-write-guard"] = function (module, exports, require) {
/*
 * Agent-mode protection.
 *
 * OpenCode's agent can edit note files directly, so a prompt instruction is
 * not enough to protect review history. Before an agent request the plugin
 * snapshots the protected properties of every question/card note. After the
 * request it restores anything the agent changed. This is a restore guard, not
 * a file-lock: body/deck/course edits are allowed, review state is not.
 */
const { PROTECTED_PROPERTIES } = require("./ai-write-guard");
const { str } = require("./util");

function cloneValue(value) {
  if (value === undefined) return undefined;
  try {
    return JSON.parse(JSON.stringify(value));
  } catch (e) {
    return value;
  }
}

function sameValue(a, b) {
  return JSON.stringify(a === undefined ? null : a) === JSON.stringify(b === undefined ? null : b);
}

function isReviewNote(fm) {
  return !!(fm && (str(fm.question_id).trim() || str(fm.card_id).trim()));
}

/** Map of note path -> protected property snapshot. */
function snapshotProtected(records) {
  const map = new Map();
  for (const record of Array.isArray(records) ? records : []) {
    const fm = (record && record.fm) || {};
    const path = (record && record.file && record.file.path) || (record && record.path) || "";
    if (!path || !isReviewNote(fm) || map.has(path)) continue;
    const state = {};
    for (const key of PROTECTED_PROPERTIES) {
      if (Object.prototype.hasOwnProperty.call(fm, key)) state[key] = cloneValue(fm[key]);
    }
    map.set(path, state);
  }
  return map;
}

/** Protected keys whose value differs from the snapshot. */
function changedProtected(before, after) {
  const old = before && typeof before === "object" ? before : {};
  const next = after && typeof after === "object" ? after : {};
  return PROTECTED_PROPERTIES.filter((key) => !sameValue(old[key], next[key]));
}

/** Apply the snapshot values back to a frontmatter object. Returns the changed keys. */
function restoreFrontmatter(target, before) {
  const fm = target && typeof target === "object" ? target : {};
  const old = before && typeof before === "object" ? before : {};
  const changes = changedProtected(old, fm);
  for (const key of changes) {
    if (Object.prototype.hasOwnProperty.call(old, key)) fm[key] = cloneValue(old[key]);
    else delete fm[key];
  }
  return changes;
}

module.exports = {
  changedProtected,
  restoreFrontmatter,
  snapshotProtected,
};
};

/* ---- src/ai-context.js ---- */
__defs["ai-context"] = function (module, exports, require) {
/*
 * Read-only study context for the assistant.
 *
 * These toggles are deliberately aggregate: counts, accuracy and the next exam.
 * Note bodies, question text, answers and personal notes are never included
 * here. A chat only receives this text when the learner has enabled the
 * matching toggle and AI features; nothing is built or sent otherwise.
 */
const { isDue } = require("./filters");
const { examCountdown, upcomingExams } = require("./calendar-model");
const { localDate, str } = require("./util");

const DEFAULT_AI_CONTEXT = { stats: false, due: false, exams: false };
const CONTEXT_KEYS = ["stats", "due", "exams"];

function normalizeAiContext(value) {
  const saved = value && typeof value === "object" ? value : {};
  const out = {};
  for (const key of CONTEXT_KEYS) out[key] = saved[key] === true;
  return out;
}

function anyContext(value) {
  const context = normalizeAiContext(value);
  return CONTEXT_KEYS.some((key) => context[key]);
}

function percent(correct, attempts) {
  if (!attempts) return "0%";
  return `${Math.round((correct / attempts) * 100)}%`;
}

function questionList(plugin) {
  try {
    return plugin && typeof plugin.getQuestions === "function" ? plugin.getQuestions() : [];
  } catch (e) {
    return [];
  }
}

function cardList(plugin) {
  try {
    return plugin && typeof plugin.getCards === "function" ? plugin.getCards() : [];
  } catch (e) {
    return [];
  }
}

function weakestSkill(questions) {
  const groups = new Map();
  for (const question of questions) {
    const fm = (question && question.fm) || {};
    const skill = str(fm.skill).trim();
    const attempts = Number(fm.attempts) || 0;
    if (!skill || attempts < 3) continue;
    const group = groups.get(skill) || { attempts: 0, correct: 0 };
    group.attempts += attempts;
    group.correct += Number(fm.correct_count) || 0;
    groups.set(skill, group);
  }
  let weakest = null;
  for (const [skill, group] of groups) {
    const accuracy = group.correct / group.attempts;
    if (!weakest || accuracy < weakest.accuracy) weakest = { skill, ...group, accuracy };
  }
  return weakest;
}

function buildStudyContext(plugin, options, now) {
  const context = normalizeAiContext(options);
  if (!anyContext(context)) return "";
  const today = localDate();
  const questions = questionList(plugin);
  const lines = ["READ-ONLY STUDY CONTEXT (aggregate vault properties only; no note text is included)."];

  if (context.stats) {
    let attempts = 0;
    let correct = 0;
    let attempted = 0;
    for (const question of questions) {
      const fm = (question && question.fm) || {};
      const n = Number(fm.attempts) || 0;
      if (!n) continue;
      attempted++;
      attempts += n;
      correct += Number(fm.correct_count) || 0;
    }
    lines.push(
      `Practice: ${questions.length} question${questions.length === 1 ? "" : "s"}; ${attempted} attempted; ` +
        `${attempts} attempt${attempts === 1 ? "" : "s"}; accuracy ${percent(correct, attempts)}.`,
    );
    const weakest = weakestSkill(questions);
    if (weakest) {
      lines.push(
        `Weakest skill with at least 3 attempts: ${weakest.skill} (${percent(weakest.correct, weakest.attempts)}, ` +
          `${weakest.attempts} attempt${weakest.attempts === 1 ? "" : "s"}).`,
      );
    }
  }

  if (context.due) {
    const due = questions.filter((question) => isDue((question && question.fm) || {}, today)).length;
    const unseen = questions.filter((question) => !Number(((question && question.fm) || {}).attempts)).length;
    const cards = cardList(plugin);
    const dueCards = cards.filter((card) => {
      const fm = (card && card.fm) || {};
      return Number(fm.attempts) > 0 && str(fm.next_review).slice(0, 10) && str(fm.next_review).slice(0, 10) <= today;
    }).length;
    const newCards = cards.filter((card) => !Number(((card && card.fm) || {}).attempts)).length;
    lines.push(
      `Due today: ${due} question${due === 1 ? "" : "s"} (${unseen} unseen), ` +
        `${dueCards} card${dueCards === 1 ? "" : "s"} due (${newCards} new).`,
    );
  }

  if (context.exams) {
    const events = typeof plugin.calendarEvents === "function" ? plugin.calendarEvents() : [];
    const exam = upcomingExams(events || [], now || new Date(), 1)[0];
    if (exam) {
      lines.push(
        `Next exam: ${str(exam.summary) || "Exam"} on ${exam.dateKey || "an unscheduled date"} ` +
          `(${examCountdown(exam, now || new Date())}).`,
      );
    } else {
      lines.push("No upcoming exam is currently loaded in the calendar.");
    }
  }

  lines.push("Use this context only when it helps; do not claim access to any note text.");
  return lines.join("\n");
}

module.exports = {
  CONTEXT_KEYS,
  DEFAULT_AI_CONTEXT,
  anyContext,
  buildStudyContext,
  normalizeAiContext,
};
};

