    conf: 1,
    desc: "",
    dyn: 0,
    extendNew: id === 1 ? 10 : 0,
    extendRev: 50,
    id,
    lrnToday: [0, 0],
    mod: now,
    name,
    newToday: [0, 0],
    revToday: [0, 0],
    timeToday: [0, 0],
    usn: -1,
