      newCardFolder: "Cards",
      defaultDeck: "General",
      reviewLimit: 20,
      order: "due",
      answerMode: "flip",
      revealAnimation: "instant",
      gradingStrictness: "standard",
      aiGrading: false,
      sameDayReviews: false,
      adaptiveFrequency: false,
      fileExplorerDue: false,
      decks: [],
      csvMappings: {},
