  let pages;
  if (kind === "pptx" || kind === "pptm") pages = await pptxPages(buf);
  else if (kind === "docx" || kind === "docm") pages = await docxPages(buf);
  else if (kind === "odt" || kind === "odp") pages = await odfPages(buf, kind);
