        kind: "card",
        cardType: "basic",
        deck: str(opts.deck).trim() || "Imported",
        front,
        back,
        title: "",
        notes: "",
        tags: [],
        importSource: opts.sourcePath || "LearnKit",
        importFormat: "learnkit",
        importKey: "",
