    needsFixing,
    needsFixingFlagged: fm.needs_fixing === true,
    needsFixingMissDays: Number(fm.needs_fixing_miss_days) || 0,
    attempts: fm.attempts,
    correctCount: fm.correct_count,
    nextReview: fm.next_review,
