    const tries = [this.ai.binaryPath, this.ai.managedBinary, path.join(os.homedir(), ".opencode", "bin", exe)].filter(Boolean);
    this.stalled = "";
    this.tooNew = null; // an OpenCode that runs but is a version this plugin can't use yet
