  nodeReq,
  OPENCODE_REPO,
  MAX_OPENCODE_MAJOR,
  opencodeMajor,
  PROVIDERS,
  platformTriple,
  candidateAssetNames,
  chooseRelease,
  mergeAuth,
  killTree,
  runCmd,
  downloadFile,
