  cos: { min: 1, max: 1, fn: (x) => Math.cos(x) },
  tan: { min: 1, max: 1, fn: (x) => Math.tan(x) },
  asin: { min: 1, max: 1, fn: (x) => Math.asin(x) },
  acos: { min: 1, max: 1, fn: (x) => Math.acos(x) },
