  CONSTANTS,
  tokenize,
  evaluateExpression,
  parseVariableSpec,
  parseVariables,
  normalizeSeed,
  mulberry32,
  buildVariant,
  substituteVariables,
  applyVariantToSections,
  formatVariantNumber,
  variantSummary,
  variantValuesText,
