      const area = (b.x1 - b.x0) * (b.y1 - b.y0);
      if (area <= 0) continue;
      const label = typeof b.s === "string" && b.s.length <= 24 && b.x1 - b.x0 < 0.3 * W; // a tick, a label, a legend entry
      const g2 = label ? near : g;
